  --space-density-control-height-standard: 40px;
  --space-density-control-height-spacious: 44px;
  --space-density-row-height-compact: 36px;
  --space-density-row-height-standard: 44px;
  --space-density-row-height-spacious: 52px;
  --space-density-panel-padding-compact: 16px;
  --space-density-panel-padding-standard: 20px;
  --space-density-panel-padding-spacious: 24px;
  --space-density-coarse-target: 44px;

  --radius-none: 0px;
  --radius-sm: 2px;
  --radius-default: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-pill: 999px;
  --radius-full: 9999px;

  /* Root density = compact (D2). */
  --density-gutter: var(--space-gutter-compact);
  --density-control-height: var(--space-density-control-height-compact);
  --density-row-height: var(--space-density-row-height-compact);
  --density-panel-padding: var(--space-density-panel-padding-compact);

  /* Effects */
  --shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-float: 0 20px 50px rgba(0, 0, 0, 0.24);
  --shadow-button: 0 1px 0 rgba(255, 255, 255, 0.05), 0 10px 24px rgba(7, 14, 28, 0.18);
  --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-modal: 0 8px 24px rgba(0, 0, 0, 0.12);
  --elevation-card: 0 1px 2px rgba(0, 0, 0, 0.04);
  --elevation-modal: 0 8px 24px rgba(0, 0, 0, 0.12);
  --ring-focus: 0 0 0 2px var(--color-background), 0 0 0 4px var(--color-ring);
  --ring-focus-shell: 0 0 0 2px var(--color-nav), 0 0 0 4px var(--color-dark-ring);
  --transition-timing-pleasant: cubic-bezier(0.2, 0.8, 0.2, 1);
  --duration-fast: 100ms;
  --duration-base: 200ms;
  --duration-reveal: 700ms;

}

