@keyframes nextlink-fade-up {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes nextlink-float {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-14px) scale(1.02); }
}
@keyframes nextlink-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}
@keyframes nextlink-brand-pulse {
  0%, 100% { opacity: 0.35; transform: scale(0.92); }
  50% { opacity: 0.85; transform: scale(1.06); }
}
@keyframes nextlink-zoom-in {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.nextlink-fade-up,
.nextlink-fade-up-delay-1,
.nextlink-fade-up-delay-2,
.nextlink-fade-up-delay-3 {
  animation: nextlink-fade-up var(--duration-reveal, 700ms) var(--transition-timing-pleasant) both;
}
.nextlink-fade-up-delay-1 { animation-delay: 120ms; }
.nextlink-fade-up-delay-2 { animation-delay: 220ms; }
.nextlink-fade-up-delay-3 { animation-delay: 320ms; }

.nextlink-float {
  animation: nextlink-float 10s ease-in-out infinite;
  transform-origin: center;
}

@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Forced colours (D1, D20): the UA drops box-shadow, so the focus ring becomes a system-colour
   outline. No surface paints gradient text, so there is no text fallback to declare. */
@media (forced-colors: active) {
  :focus-visible {
    outline: 2px solid !important;
    outline-offset: 2px !important;
    box-shadow: none !important;
  }
}

/* Print (D20): the fixed shell is hidden, the body prints light, cards and rows stay whole. */
@media print {
  [data-slot="app-shell-header"],
  [data-slot="app-shell-sidebar"],
  [data-slot="app-shell-drawer"],
  [data-slot="top-bar"],
  .nextlink-sidebar-gradient {
    display: none !important;
  }
  body {
    background: var(--color-neutral-white, #fff);
    color: var(--color-neutral-black, #303030);
  }
  [data-slot="card"],
  tr {
    break-inside: avoid;
  }
}

/* Coarse pointers (D8): controls and rows grow to the 44px target at every density. */
@media (pointer: coarse) {
  :root,
  [data-density] {
    --density-control-height: var(--space-density-coarse-target);
    --density-row-height: var(--space-density-coarse-target);
  }
}

