  --space-gutter-spacious: 32px;
  --space-sidebar-width: 240px;
  --space-sidebar-collapsed: 56px;
  --space-topbar-height: 56px;
  --space-content-max: 1280px;
  --space-density-control-height-compact: 36px;
  --space-density-control-height-standard: 40px;
  --space-density-control-height-spacious: 44px;
  --space-density-row-height-compact: 36px;
  --space-density-row-height-standard: 44px;
  --space-density-row-height-spacious: 52px;
  --space-density-panel-padding-compact: 16px;
  --space-density-panel-padding-standard: 20px;
  --space-density-panel-padding-spacious: 24px;
  --space-density-coarse-target: 44px;

  /* Root density = compact (D2). */
  --density-gutter: var(--space-gutter-compact);
  --density-control-height: var(--space-density-control-height-compact);
  --density-row-height: var(--space-density-row-height-compact);
  --density-panel-padding: var(--space-density-panel-padding-compact);
}

/* Dark mode (first-class default product posture). */
.dark,
[data-theme="dark"] {
  --background: #08111F;
  --foreground: #F7FAFF;
  --card: #101B2D;
  --card-foreground: #F7FAFF;
  --surface: #101B2D;
  --surface-raised: #121F33;
  --primary: #1D5BD6;
  --primary-foreground: #FFFFFF;
  --primary-soft: rgba(143, 179, 255, 0.16);
  --brand-soft: rgba(143, 179, 255, 0.16);
  --secondary: #121F33;
  --secondary-foreground: #D7E2F1;
  --tertiary: #FAA21B;
  --tertiary-foreground: #08111F;
  --tertiary-soft: rgba(250, 162, 27, 0.16);
  --priority-soft: rgba(250, 162, 27, 0.16);
  --muted: #121F33;
  --muted-foreground: #A7B5C8;
  --popover: #121F33;
  --popover-foreground: #F7FAFF;
  --accent: #17263D;
  --accent-foreground: #F7FAFF;
  --destructive: #FF4D4F;
  --destructive-foreground: #FFFFFF;
  --border: #21324A;
  --input: #21324A;
  --ring: #8FB3FF;
  --link: #8FB3FF;
  --info: #79C8FF;
  --success: #4FD6A2;
  --warning: #F3C35B;
  --danger: #FF7B8F;
  --processing: #27C2D1;
  --neutral-status: #A7B5C8;
  --priority-emphasis: #FAA21B;
  --theme-chart-1: #79C8FF;
  --theme-chart-2: #27C2D1;
  --theme-chart-3: #4FD6A2;
  --theme-chart-4: #F3C35B;
  --theme-chart-5: #E26BFF;
  --theme-chart-6: #79C8FF;
  --warn: var(--warning);
  --priority: var(--priority-emphasis);
  --accent-notice: var(--warning);
  --accent-negative: var(--danger);
  --accent-positive: var(--success);
  --accent-info: var(--info);
  --accent-processing: var(--processing);
  --radius: 4px;

  --elevation-card: 0 1px 2px rgba(0, 0, 0, 0.24);
  --elevation-modal: 0 8px 24px rgba(0, 0, 0, 0.4);
}

[data-density="compact"] {
  --density-gutter: var(--space-gutter-compact);
  --density-control-height: var(--space-density-control-height-compact);
  --density-row-height: var(--space-density-row-height-compact);
  --density-panel-padding: var(--space-density-panel-padding-compact);
}

[data-density="standard"] {
  --density-gutter: var(--space-gutter-standard);
  --density-control-height: var(--space-density-control-height-standard);
  --density-row-height: var(--space-density-row-height-standard);
  --density-panel-padding: var(--space-density-panel-padding-standard);
}

[data-density="spacious"] {
  --density-gutter: var(--space-gutter-spacious);
  --density-control-height: var(--space-density-control-height-spacious);
  --density-row-height: var(--space-density-row-height-spacious);
  --density-panel-padding: var(--space-density-panel-padding-spacious);
}

body {
  @apply bg-background text-foreground font-sans antialiased;
  min-height: 100vh;
}

/* Element defaults sit in @layer base so Tailwind utilities keep winning. */
@layer base {
  a { color: var(--color-link); text-decoration: none; text-underline-offset: 4px; }
  a:hover { text-decoration: underline; }
  code, kbd, pre, samp { font-family: var(--font-mono); }
  ::selection { background: var(--color-primary); color: var(--color-primary-foreground); }
}

.nextlink-grid-pattern {
  background-image: linear-gradient(to right, rgba(255, 255, 255, 0.06) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
  background-size: 48px 48px;
}

.nextlink-preview-backdrop {
  background-image: radial-gradient(circle at top left, color-mix(in srgb, var(--color-identity-blue) 10%, transparent), transparent 32%),
    radial-gradient(circle at bottom right, color-mix(in srgb, var(--color-identity-gold) 6%, transparent), transparent 28%);
}

.nextlink-sidebar-gradient {
  background: linear-gradient(160deg, var(--color-nav) 0%, var(--color-dark-bg) 40%, var(--color-dark-bgsub) 100%);
}

.nextlink-thin-scroll {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
}

@keyframes nextlink-fade-up {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes nextlink-float {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-14px) scale(1.02); }
}
@keyframes nextlink-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}
@keyframes nextlink-brand-pulse {
  0%, 100% { opacity: 0.35; transform: scale(0.92); }
  50% { opacity: 0.85; transform: scale(1.06); }
}
@keyframes nextlink-zoom-in {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.nextlink-fade-up,
.nextlink-fade-up-delay-1,
.nextlink-fade-up-delay-2,
.nextlink-fade-up-delay-3 {
  animation: nextlink-fade-up var(--duration-reveal, 700ms) var(--transition-timing-pleasant) both;
}
.nextlink-fade-up-delay-1 { animation-delay: 120ms; }
.nextlink-fade-up-delay-2 { animation-delay: 220ms; }
.nextlink-fade-up-delay-3 { animation-delay: 320ms; }

.nextlink-float {
  animation: nextlink-float 10s ease-in-out infinite;
  transform-origin: center;
}

@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Forced colours (D1, D20): the UA drops box-shadow, so the focus ring becomes a system-colour
   outline. No surface paints gradient text, so there is no text fallback to declare. */
@media (forced-colors: active) {
  :focus-visible {
    outline: 2px solid !important;
    outline-offset: 2px !important;
    box-shadow: none !important;
  }
}

/* Print (D20): the fixed shell is hidden, the body prints light, cards and rows stay whole. */
@media print {
  [data-slot="app-shell-header"],
  [data-slot="app-shell-sidebar"],
  [data-slot="app-shell-drawer"],
  [data-slot="top-bar"],
  .nextlink-sidebar-gradient {
    display: none !important;
  }
  body {
    background: var(--color-neutral-white, #fff);
    color: var(--color-neutral-black, #303030);
  }
  [data-slot="card"],
  tr {
    break-inside: avoid;
  }
}

/* Coarse pointers (D8): controls and rows grow to the 44px target at every density. */
@media (pointer: coarse) {
  :root,
  [data-density] {
    --density-control-height: var(--space-density-coarse-target);
    --density-row-height: var(--space-density-coarse-target);
  }
}
